begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select is((select contract_code from jsonb_to_record(public.app_context()) as x(contract_code text)),'cv_app_db_2','only current database contract is exposed');
select ok((select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('admin','ai','legal','cv','audit') and c.relkind='r'),'every private business table has RLS');
select is((select count(*) from information_schema.columns where table_schema in('ai','legal','audit') and data_type in('json','jsonb')),0::bigint,'AI/legal/history have only typed columns');
select ok(not has_schema_privilege('authenticated','ai','USAGE') and not has_schema_privilege('service_role','ai','USAGE'),'neither client nor service role gets private schema access');
select ok(not has_function_privilege('authenticated','public.ai_reserve(jsonb)','EXECUTE') and has_function_privilege('service_role','public.ai_reserve(jsonb)','EXECUTE'),'service-only reserve ACL');
select ok(not has_function_privilege('service_role','public.admin_read(jsonb)','EXECUTE') and has_function_privilege('authenticated','public.admin_read(jsonb)','EXECUTE'),'Admin requires a real client actor');
select ok(has_function_privilege('anon','public.legal_current()','EXECUTE') and has_function_privilege('anon','public.keep_project_active()','EXECUTE'),'anonymous exact legal reads and keepalive remain available');
select is(public.keep_project_active(),true,'keepalive is strict boolean true');
select ok((select bool_and(not rolcanlogin and not rolinherit and not rolbypassrls and not rolsuper and not rolcreaterole and not rolcreatedb and not rolreplication) from pg_roles where rolname='app_api_owner'),'API owner has no dangerous role attributes');
select is((select count(*) from pg_auth_members m join pg_roles r on r.oid=m.member where r.rolname='app_api_owner'),0::bigint,'API owner has no outgoing membership');
select ok((select bool_and(prosecdef and proowner=(select oid from pg_roles where rolname='app_api_owner') and array_to_string(proconfig,',') like '%search_path=""%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and proname<>'keep_project_active'),'public definers are safely owned with empty search path');
select ok((select prosecdef and proowner=(select oid from pg_roles where rolname='app_api_owner') from pg_proc where oid='ai.validate_rule_graph()'::regprocedure),'deferred graph checker retains private access after authenticated RPC returns');
select ok(not has_function_privilege('authenticated','ai.validate_rule_graph()','EXECUTE'),'deferred trigger checker has no client execute');
select lives_ok($$select common.assert_api_owner_safe()$$,'owner hardening checks Auth/Storage table/column privileges and memberships');
select is((select count(*) from legal.documents where enabled),5::bigint,'current typed catalog has ordinary/common/three recipient documents');
select ok((select bool_and(content_digest ~ '^[a-f0-9]{64}$' and document_audit_id is not null) from legal.documents),'every document has exact digest and immutable history target');
select ok((select bool_and(position('##' in zh_body)>0 and position('##' in en_body)>0) from legal.documents),'both languages contain canonical Markdown');
select throws_ok($$insert into ai.routing_rules(weekday,start_minute,end_minute) values(1,null,10)$$,'23514',null,'partial NULL periods are rejected by table constraint');
select throws_ok($$insert into ai.routing_rules(weekday,start_minute,end_minute) values(1,10,10)$$,'23514',null,'empty time periods are rejected');
select throws_ok($$update audit.documents set zh_body='corrupt'$$,'P0001','INVALID_REQUEST','typed legal history cannot be rewritten');
select throws_ok($$delete from audit.documents$$,'P0001','INVALID_REQUEST','typed legal history cannot be deleted');
select throws_ok($$select public.admin_context()$$,'P0001','UNAUTHORIZED','Admin RPC never trusts database connection role as Auth actor');
select * from finish();
rollback;
